1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Derives an owner's membership points and the numeric membership level mapped from them.
10	 * Points start at 0 and gain: 2 when an email is present, 1 when {@code namesakeCount} is 0,
11	 * 2 for a household of 3 or more members, and 3 for tenure over 365 days (measured from
12	 * {@code registrationDate}). Points map to a level (1 to 4): 1 for 0-1 points, 2 for 2-3,
13	 * 3 for 4-5 and 4 for 6 or more.
14	 */
15	public final class MembershipLevel {
16	
17	    /** Points awarded when an email is present. */
18	    private static final int EMAIL_POINTS = 2;
19	
20	    /** Points awarded when the owner has no namesakes. */
21	    private static final int NO_NAMESAKE_POINTS = 1;
22	
23	    /** Points awarded for a household of {@link #HOUSEHOLD_THRESHOLD} or more members. */
24	    private static final int HOUSEHOLD_POINTS = 2;
25	
26	    /** Household size at or above which household points are awarded. */
27	    private static final int HOUSEHOLD_THRESHOLD = 3;
28	
29	    /** Points awarded when tenure exceeds {@link #TENURE_DAYS} days. */
30	    private static final int TENURE_POINTS = 3;
31	
32	    /** Tenure (in days) beyond which an owner earns tenure points. */
33	    private static final long TENURE_DAYS = 365;
34	
35	    private MembershipLevel() {
36	    }
37	
38	    /** Membership points derived from the owner's email, namesake count, household size and tenure. */
39	    public static int points(Owner owner) {
40	        int points = 0;
41	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
42	            points += EMAIL_POINTS;
43	        }
44	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
45	            points += NO_NAMESAKE_POINTS;
46	        }
47	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_THRESHOLD) {
48	            points += HOUSEHOLD_POINTS;
49	        }
50	        if (tenureDays(owner) > TENURE_DAYS) {
51	            points += TENURE_POINTS;
52	        }
53	        return points;
54	    }
55	
56	    /** Membership level (1 to 4) mapped from the owner's {@link #points(Owner) membership points}. */
57	    public static int of(Owner owner) {
58	        int points = points(owner);
59	        if (points >= 6) {
60	            return 4;
61	        }
62	        if (points >= 4) {
63	            return 3;
64	        }
65	        if (points >= 2) {
66	            return 2;
67	        }
68	        return 1;
69	    }
70	
71	    /** Days elapsed since the owner's registrationDate; 0 when the date is absent or in the future. */
72	    private static long tenureDays(Owner owner) {
73	        LocalDate registrationDate = owner.getRegistrationDate();
74	        if (registrationDate == null) {
75	            return 0;
76	        }
77	        long days = ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
78	        return Math.max(days, 0);
79	    }
80	}
